create or replace function public.delete_class_phase(_class uuid,_key text) returns void language plpgsql security definer set search_path=public as $$ declare c public.classes; keys text[]; begin select * into c from public.classes where id=_class for update; if not found or not public.has_tenant_role(auth.uid(),c.tenant_id,'{coach,admin}') then raise exception 'No autorizado'; end if; select array_agg(p->>'key') into keys from jsonb_array_elements(c.phases) p where p->>'key'=_key or p->>'alternativeTo'=_key; delete from public.wod_items where class_id=c.id and block=any(keys); update public.classes set phases=coalesce((select jsonb_agg(p) from jsonb_array_elements(c.phases) p where not (p->>'key'=any(keys))),'[]'::jsonb) where id=c.id; end; $$;
revoke execute on function public.delete_class_phase(uuid,text) from public,anon; grant execute on function public.delete_class_phase(uuid,text) to authenticated;
comment on function public.delete_class_phase(uuid,text) is 'Authenticated teacher-only atomic phase deletion: authorizes same-tenant coach/admin before modifying class-owned rows.';
update public.classes c set phases=(select jsonb_agg(q.value order by q.ord,q.sub) from (select p.value || '{"alternatives":""}'::jsonb as value,p.ordinality as ord,0 as sub from jsonb_array_elements(c.phases) with ordinality p union all select jsonb_build_object('key',(p.value->>'key')||'-alternative','title',p.value->>'alternatives','alternatives','','alternativeTo',p.value->>'key'),p.ordinality,1 from jsonb_array_elements(c.phases) with ordinality p where coalesce(p.value->>'alternatives','')<>'') q) where exists(select 1 from jsonb_array_elements(c.phases) p where coalesce(p->>'alternatives','')<>'');
insert into public.wod_items(tenant_id,class_id,block,position,label,alternative_to) select tenant_id,class_id,block,position,alternatives,id from public.wod_items where coalesce(alternatives,'')<>'' and alternative_to is null;
update public.wod_items set alternatives=null where alternatives is not null;